"""Transport fixtures only; actual immutable Git package/checkpoint validation."""
import copy,importlib.util,json,os,pathlib,unittest
from unittest import mock
P=pathlib.Path('/workspace/work/adopt2121-20261008')
path=P/os.environ.get('PARTIAL_FACTS_UNDER_TEST','partial-snapshot-facts.py')
s=importlib.util.spec_from_file_location('facts',path);r=importlib.util.module_from_spec(s);s.loader.exec_module(r)
class Contract(unittest.TestCase):
    def run_facts(self,name,mutation=None):
        d=r.common.read(P/'partial-snapshot-fresh-preparation-boundaries.json')[name];req=r.common.read(P/(name+'-adapter/start-request.json'))
        f={'head':d['source_head'],'lease':copy.deepcopy(d['lease']),'watchdog':{'repository':req['lease_repository'],'source_ref':req['lease_source_ref'],'is_enabled':False,'last_run_at_utc':None,'observed_at_utc':r.common.now(),'source':'actual automations.peek receipt'}}
        if mutation:mutation(f)
        original=r.common.git
        def git(repo,*args):
            if args[0]=='ls-remote':return f['head']+'\t'+args[-1]
            if args[0]=='fetch':return ''
            return original(repo,*args)
        class Store:
            def __init__(self,*a):pass
            def read(self):return d['coordination_revision'],f['lease']
        with mock.patch.object(r.common,'git',git),mock.patch.object(r,'GitLeaseStore',Store):return r.facts(name,f['watchdog'])
    def test_rebound_switcher_and_original_gad_validate_actual_objects(self):
        for n in ['gad','switcher']:
            d=self.run_facts(n);self.assertEqual(d['source_head'],json.loads((P/'partial-snapshot-selection.json').read_text())['source_bindings'][n]['source_head']);self.assertEqual(d['snapshot']['package_fingerprint'],'git-tree:9c45d98c3254e9658d452c505d8c97698e3fc9a7');self.assertFalse(d['snapshot']['watchdog']['enabled'])
    def test_changed_head_live_owner_guard_stale_and_enabled_rejected(self):
        for mutate in [lambda x:x.update(head='a'*40),lambda x:x['lease'].update(owner_id='live'),lambda x:x['lease'].update(external_guard={'state':'running'}),lambda x:x['watchdog'].update(is_enabled=True),lambda x:x['watchdog'].update(observed_at_utc='2020-01-01T00:00:00Z')]:
            with self.assertRaises(AssertionError):self.run_facts('switcher',mutate)
    def test_gpc_is_not_selected_or_eligible_write_target(self):
        self.assertEqual(r.selection()['selected'],['gad','switcher'])
        with self.assertRaises(AssertionError):self.run_facts('gpc')
if __name__=='__main__':unittest.main(verbosity=2)
